// Bit-exact parity test: C++ MTP foundation vs vectors generated by the REAL
// Python MTP head + Sampler.verify_point_mass (tools/gen_mtp_vectors.py).
// Compares raw bytes (uint32 view), not tolerances. No checkpoint used.
//
// Generate vectors first:
//   /Users/vincent/Documents/Veystrix/.venv/bin/python \
//     cpp/engine/tools/gen_mtp_vectors.py --out cpp/engine/tests/vectors_mtp
#include "../src/mtp.hpp"

#include <mlx/mlx.h>

#include <cctype>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

namespace mx = mlx::core;
using namespace veystrix::engine;

static std::string read_all(const std::string& path) {
  std::ifstream f(path);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

// First differing uint32 view index, or a.size() when equal.
static size_t first_diff(const mx::array& a, const mx::array& b, bool& shape_ok) {
  shape_ok = (a.shape() == b.shape());
  if (!shape_ok) return 0;
  mx::array av = mx::astype(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::astype(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) { shape_ok = false; return 0; }
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return i;
  return av.size();
}

static bool find_num(const std::string& s, const std::string& key, double& out) {
  auto k = s.find("\"" + key + "\"");
  if (k == std::string::npos) return false;
  auto colon = s.find(':', k);
  if (colon == std::string::npos) return false;
  size_t i = colon + 1;
  while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
  size_t j = i;
  while (j < s.size() && (std::isdigit(static_cast<unsigned char>(s[j])) ||
                          s[j] == '-' || s[j] == '+' || s[j] == '.' ||
                          s[j] == 'e' || s[j] == 'E')) ++j;
  out = std::stod(s.substr(i, j - i));
  return true;
}

static std::vector<int32_t> find_int_array(const std::string& s,
                                           const std::string& key) {
  std::vector<int32_t> out;
  auto k = s.find("\"" + key + "\"");
  if (k == std::string::npos) return out;
  auto lb = s.find('[', k);
  auto rb = s.find(']', k);
  if (lb == std::string::npos || rb == std::string::npos || rb < lb) return out;
  std::string body = s.substr(lb + 1, rb - lb - 1);
  size_t i = 0;
  while (i < body.size()) {
    while (i < body.size() && !std::isdigit(static_cast<unsigned char>(body[i])) &&
           body[i] != '-') ++i;
    if (i >= body.size()) break;
    size_t j = i;
    while (j < body.size() && (std::isdigit(static_cast<unsigned char>(body[j])) ||
                               body[j] == '-')) ++j;
    out.push_back(static_cast<int32_t>(std::stoi(body.substr(i, j - i))));
    i = j;
  }
  return out;
}

static int run_verify_case(const std::string& root, const std::string& name) {
  std::string dir = root + "/verify/" + name;
  auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };
  std::string meta = read_all(dir + "/result.json");

  double vocab_d, temp, topp, topk_d, minp, pen, seed_d;
  find_num(meta, "vocab", vocab_d);
  find_num(meta, "temperature", temp);
  find_num(meta, "top_p", topp);
  find_num(meta, "top_k", topk_d);
  find_num(meta, "min_p", minp);
  find_num(meta, "presence_penalty", pen);
  find_num(meta, "seed", seed_d);
  double exp_accepted, exp_token;
  find_num(meta, "accepted", exp_accepted);
  find_num(meta, "next_token", exp_token);
  std::vector<int32_t> seen = find_int_array(meta, "seen");

  mx::array rows = load("rows");
  mx::array drafts_arr = load("drafts");
  mx::eval(rows, drafts_arr);
  const int ndraft = static_cast<int>(drafts_arr.shape(0));
  std::vector<int32_t> drafts(ndraft);
  mx::array d32 = mx::astype(mx::reshape(drafts_arr, {-1}), mx::int32);
  mx::eval(d32);
  const int32_t* dp = d32.data<int32_t>();
  for (int i = 0; i < ndraft; ++i) drafts[i] = dp[i];

  mx::array rows2d = mx::reshape(rows, {ndraft + 1, static_cast<int>(vocab_d)});
  std::vector<mx::array> row_list;
  for (int i = 0; i < ndraft + 1; ++i)
    row_list.push_back(mx::slice(rows2d, {i, 0}, {i + 1, static_cast<int>(vocab_d)},
                                 {1, 1}));

  SamplingParams p;
  p.temperature = static_cast<float>(temp);
  p.top_p = static_cast<float>(topp);
  p.top_k = static_cast<int>(topk_d);
  p.min_p = static_cast<float>(minp);
  p.presence_penalty = static_cast<float>(pen);

  MTPVerifyResult r = mtp_verify(row_list, drafts, p,
                                 static_cast<uint64_t>(seed_d), seen);
  if (r.accepted != static_cast<int>(exp_accepted) ||
      r.next_token != static_cast<int32_t>(exp_token)) {
    std::fprintf(stderr,
                 "[%s] VERIFY differs: accepted %d (exp %d), token %d (exp %d)\n",
                 name.c_str(), r.accepted, static_cast<int>(exp_accepted),
                 r.next_token, static_cast<int32_t>(exp_token));
    return 1;
  }
  std::printf("  [%s] OK (accepted=%d token=%d)\n", name.c_str(), r.accepted,
              r.next_token);
  return 0;
}

int main(int argc, char** argv) {
  std::string root = argc > 1 ? argv[1] : "cpp/engine/tests/vectors_mtp";
  std::string cfg = read_all(root + "/config.json");
  if (cfg.empty()) {
    std::fprintf(stderr, "config.json missing; run gen_mtp_vectors.py\n");
    return 2;
  }

  MTPConfig c;
  double v;
  find_num(cfg, "hidden_size", v); c.hidden_size = static_cast<int>(v);
  find_num(cfg, "hc_count", v); c.hc_count = static_cast<int>(v);
  find_num(cfg, "hc_lowrank", v); c.hc_lowrank = static_cast<int>(v);
  find_num(cfg, "n_heads", v); c.n_heads = static_cast<int>(v);
  find_num(cfg, "n_kv_heads", v); c.n_kv_heads = static_cast<int>(v);
  find_num(cfg, "head_dim", v); c.head_dim = static_cast<int>(v);
  find_num(cfg, "n_experts", v); c.n_experts = static_cast<int>(v);
  find_num(cfg, "top_k", v); c.top_k = static_cast<int>(v);
  find_num(cfg, "inter", v); c.inter = static_cast<int>(v);
  find_num(cfg, "shared_inter", v); c.shared_inter = static_cast<int>(v);
  find_num(cfg, "vocab", v); c.vocab = static_cast<int>(v);
  find_num(cfg, "eps", v); c.eps = static_cast<float>(v);
  find_num(cfg, "rope_base", v); c.rope_base = static_cast<float>(v);
  find_num(cfg, "partial_rotary_factor", v); c.partial_rotary_factor = static_cast<float>(v);
  find_num(cfg, "position", v); c.position = static_cast<int>(v);
  find_num(cfg, "indexer_n_heads", v); c.indexer_n_heads = static_cast<int>(v);
  find_num(cfg, "indexer_head_dim", v); c.indexer_head_dim = static_cast<int>(v);
  find_num(cfg, "indexer_budget", v); c.indexer_budget = static_cast<int>(v);
  find_num(cfg, "indexer_compress_ratio", v); c.indexer_compress_ratio = static_cast<int>(v);
  c.mrope_section = find_int_array(cfg, "mrope_section");

  auto wload = [&](const char* n) { return mx::load(root + "/weights/" + n + ".npy"); };
  MTPWeights w(
      wload("emb"),
      wload("pre_fc_norm_embedding.weight"), wload("fc_embedding.weight"),
      wload("pre_fc_norm_hidden.weight"), wload("fc_hidden.weight"),
      wload("attn_hc_norm.weight"), wload("attn_down.weight"),
      wload("attn_up.weight"), wload("attn_inject.weight"),
      wload("q_proj.weight"), wload("k_proj.weight"), wload("v_proj.weight"),
      wload("o_proj.weight"), wload("q_norm.weight"), wload("k_norm.weight"),
      wload("mlp_hc_norm.weight"), wload("mlp_down.weight"),
      wload("mlp_up.weight"), wload("mlp_inject.weight"),
      wload("gate.weight"), wload("sw_gate.weight"), wload("sw_up.weight"),
      wload("sw_down.weight"), wload("shared_gate.weight"),
      wload("shared_up.weight"), wload("shared_down.weight"),
      wload("shared_gate_logits.weight"),
      wload("mix_hc_norm.weight"), wload("mix_down.weight"),
      wload("mix_up.weight"));

  auto load = [&](const char* n) { return mx::load(root + "/" + n + ".npy"); };
  mx::array hidden = load("hidden");
  mx::array next_tokens = load("next_tokens");
  mx::array exp_fused = load("fuse_inputs");
  mx::array exp_logits = load("logits");

  bool shape_ok = true;
  int failed = 0;

  // 1) MTP-specific fusion primitive.
  mx::array fused = mtp_fuse_inputs(
      c, w, mx::take(w.emb, mx::astype(next_tokens, mx::int32), -2), hidden);
  mx::eval(fused);
  size_t diff = first_diff(fused, exp_fused, shape_ok);
  if (!shape_ok || diff != exp_fused.size()) {
    std::fprintf(stderr, "FUSE_INPUTS differs: shape_ok=%d diff=%zu size=%zu\n",
                 shape_ok, diff, exp_fused.size());
    failed++;
  } else {
    std::printf("  fuse_inputs OK (%zu bytes bit-identical)\n", exp_fused.size() * 4);
  }

  // 2) Full draft head forward -> logits.
  mx::array logits = mtp_draft_forward(c, w, hidden, next_tokens);
  mx::eval(logits);
  diff = first_diff(logits, exp_logits, shape_ok);
  if (!shape_ok || diff != exp_logits.size()) {
    std::fprintf(stderr, "DRAFT LOGITS differ: shape_ok=%d diff=%zu size=%zu\n",
                 shape_ok, diff, exp_logits.size());
    failed++;
  } else {
    std::printf("  draft logits OK (%zu bytes bit-identical)\n",
                exp_logits.size() * 4);
  }

  // 3) Verify / accept-reject.
  std::string cases_txt = read_all(root + "/verify/cases.txt");
  std::istringstream cs(cases_txt);
  std::string name;
  int nv = 0;
  while (std::getline(cs, name)) {
    if (name.empty()) continue;
    failed += run_verify_case(root, name);
    nv++;
  }

  if (failed) {
    std::fprintf(stderr, "%d MTP check(s) FAILED\n", failed);
    return 1;
  }
  std::printf("test_mtp OK (fuse_inputs + draft logits bit-identical; %d verify cases)\n", nv);
  return 0;
}
